mapper.select:
select a.service_contract_id, a.form_id, a.company, a.`name`, a.`code`, ROUND(a.amount, 2) as amount, a.project_code, DATE_FORMAT(a.signing_time, '%Y-%m-%d') AS signing_time, DATE_FORMAT(a.service_start_time, '%Y-%m-%d') AS service_start_time, DATE_FORMAT(a.service_end_time, '%Y-%m-%d') AS service_end_time, a.service_unit, DATE_FORMAT(a.project_start_time, '%Y-%m-%d') AS project_start_time, DATE_FORMAT(a.project_end_time, '%Y-%m-%d') AS project_end_time, a.content, a.OWNER, a.pm, a.flag, a.`status`, b.NAME AS service_provider, a.service_unit AS organization_id, g.satisfaction, g.evaluate from sc_service_contract a LEFT JOIN b_organization b ON b.organization_id = a.service_unit LEFT JOIN sc_contract_evaluate g ON g.service_contract_id = a.service_contract_id LEFT JOIN wf_form c ON c.form_id = a.form_id LEFT JOIN b_user d ON d.user_id = c.create_user_id where a.flag = 1 and c.create_user_id = #{listParam.userId}
/*数据范围：所有*/
/*数据范围：当前租户*/ and a.tenant_id = #{userInfo.tenantId}
/*数据范围：集团*/ and a.tenant_id = #{userInfo.tenantId}
/*数据范围：公司*/ and a.service_unit in
#{org.id}
/*数据范围：个人*/ and c.create_user_id = #{userInfo.userId}
and a.tenant_id = #{listParam.tenantId}
and a.status = #{listParam.searchMap.status}
and a.name like CONCAT('%',#{listParam.searchMap.name},'%')
order by a.modify_time DESC

select a.service_contract_id, a.form_id, a.company, a.`name`, a.`code`, ROUND(a.amount, 2) as amount, a.project_code, DATE_FORMAT(a.signing_time, '%Y-%m-%d') AS signing_time, DATE_FORMAT(a.service_start_time, '%Y-%m-%d') AS service_start_time, DATE_FORMAT(a.service_end_time, '%Y-%m-%d') AS service_end_time, a.service_unit, DATE_FORMAT(a.project_start_time, '%Y-%m-%d') AS project_start_time, DATE_FORMAT(a.project_end_time, '%Y-%m-%d') AS project_end_time, a.content, a.OWNER, a.pm, a.flag, a.`status`, b.NAME AS service_provider, g.satisfaction, g.evaluate from sc_service_contract a LEFT JOIN b_organization b ON b.organization_id = a.service_unit LEFT JOIN sc_contract_evaluate g ON g.service_contract_id = a.service_contract_id LEFT JOIN wf_form c ON c.form_id = a.form_id LEFT JOIN b_user d ON d.user_id = c.create_user_id where c.form_id = #{formId} AND a.flag != -1
/*数据范围：所有*/
/*数据范围：当前租户*/ and a.tenant_id = #{userInfo.tenantId}
/*数据范围：集团*/ and a.tenant_id = #{userInfo.tenantId}
/*数据范围：公司*/ and a.service_unit in
#{org.id}
/*数据范围：个人*/ and a.create_user_id = #{userInfo.userId}

